package dev.mixer.android;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;
/** Typed small projections accompany the complete raw trace; observations do not grant helper-return credit. */
public final class CompactEvidence {
 private CompactEvidence(){}
 static PrintWriter writer(Path path)throws IOException{return new PrintWriter(new OutputStreamWriter(Files.newOutputStream(path),StandardCharsets.UTF_8));}
 private static int integer(Object value){if(!(value instanceof Integer number)||number<0)throw new AssertionError("exact nonnegative event/frame index");return number;}
 private static List<Object> points(Map<String,Object> row){List<Object> points=new ArrayList<>();Object selected=row.get("selected");if(selected instanceof Map<?,?> map&&!map.isEmpty())points.add(selected);Object events=row.get("selected_event");if(events instanceof List<?> list)points.addAll(list);else if(events instanceof Map<?,?>)points.add(events);return points;}
 static Map<String,Object> project(Map<String,Object> row){
  Map<String,Object> out=new LinkedHashMap<>(row);List<Object> sequence=Json.array(row.get("native_sequence")),sets=Json.array(row.get("frame_sets"));out.remove("native_sequence");out.remove("frame_sets");out.remove("actual_native_outcomes");List<Object> selected=new ArrayList<>();Set<Integer> selectedIndexes=new HashSet<>();
  for(Object value:points(row)){Map<String,Object> point=Json.object(value);int index=integer(point.get("sequence_index"));Map<String,Object> event=Json.object(sequence.get(index));int frames=integer(event.get("frame_set"));if(integer(point.get("frame_set"))!=frames)throw new AssertionError("selected immutable event/frame association");selected.add(Map.of("sequence_index",index,"native_event",event,"production_frames",sets.get(frames)));selectedIndexes.add(index);}
  out.put("selected_immutable_event_points",selected);
  Object receiver=row.get("original_target");if(receiver==null&&row.get("original_authority") instanceof Map<?,?> authority)receiver=authority.get("receiver");if(receiver==null&&row.get("selected") instanceof Map<?,?> target&&target.get("receiver_authority") instanceof Map<?,?> authority)receiver=authority.get("receiver");String method=row.get("selected_leaf") instanceof String leaf?leaf:row.get("historical_id")!=null?String.valueOf(Json.object(row.get("selected")).get("native_method")):row.containsKey("original_attempt_close")?"BaseInputConnection.closeConnection":row.get("family") instanceof String family?"BaseInputConnection."+family:null;
  List<Object> outcomes=new ArrayList<>();for(Object value:Json.array(row.get("actual_native_outcomes"))){Map<String,Object> observed=Json.object(value);if(Objects.equals(observed.get("method"),method)&&Objects.equals(observed.get("receiver_identity"),receiver))outcomes.add(observed);}out.put("same_receiver_native_completion_candidates",outcomes);out.put("completion_candidate_scope","Actual recorded completions for same named leaf/receiver; checker must join exact invocation/event pair. No missing native/helper result is inferred.");
  Map<String,Integer> counts=new TreeMap<>();Map<String,Object> invocations=new TreeMap<>();MessageDigest digest;try{digest=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException failure){throw new AssertionError(failure);}
  for(Object value:sequence){Map<String,Object> event=Json.object(value);String key=event.get("method")+"/"+event.get("phase");counts.merge(key,1,Integer::sum);String canonical=DirectBoundaryStates.json(event);byte[] bytes=canonical.getBytes(StandardCharsets.UTF_8);digest.update((byte)(bytes.length>>>24));digest.update((byte)(bytes.length>>>16));digest.update((byte)(bytes.length>>>8));digest.update((byte)bytes.length);digest.update(bytes);for(Object frame:Json.array(sets.get(integer(event.get("frame_set"))))){String frameKey=DirectBoundaryStates.json(frame);invocations.putIfAbsent(frameKey,frame);}}
  out.put("ordered_native_event_digest",HexFormat.of().formatHex(digest.digest()));out.put("native_event_count",sequence.size());out.put("native_event_counts",counts);out.put("distinct_actual_product_invocation_frames",new ArrayList<>(invocations.values()));out.put("observed_frame_scope","Actual runtime source-method/descriptor/BCI presence only. Ancestor frames are enclosing observations; no automatic native-callback or helper-return credit.");out.put("complete_raw_trace_retained",true);return out;
 }
}
